function data = pekanimproanalysis(nmat,wlen,tmin,tmax,col,stat);%function data = improanalysis(nmat,wlen,<tmin>,<tmax>,<col>,<stat>);% input parameters:%   NMAT = note matrix to be analysed%   WLEN = length of analysis window in secs%   TMIN (optional, default = 0) = start point of analysis in secs%   TMAX (optional, default = end of NMAT) = end point of analysis in secs%   COL (optional, default=0) = output color%       0 = color output for screen%       1 = b/w output for printout%warning offwstep=1;if nargin<6 stat=0; endif nargin<5 col=0; endif nargin<3 tmin=0; endif nargin<2    wlen=6; disp('Window length set to 6 secs.');endif nargin<4    on=onset(nmat,'sec');    du=dur(nmat,'sec');    tmax=on(end)+du(end);    tmin=on(1);endif col==0    c1='k-'; c2='g-';else    c1='k-'; c2='k--';endnm=shift(onsetwindow(nmat,tmin,tmax,'sec'),'onset',-tmin);totdur = nm(end,end-1);mc=mchannels(nmat);if length(mc)==1    disp(['Data found on 1 channel only!']);elseif length(mc)>2    disp(['Data found on ' num2str(length(mc)) ' channels!']);    disp('First 2 channels displayed.');endif isstruct(stat)    if isstruct(stat.dens)        structstat = 1;    else        structstat = 0;    endelse    structstat = 0;endnm1=getmidich(nm,mc(1));%maxkkcc(nm1(1,:)); % In order to force the taking into account of these functions my Matlab Compiler. See compiler manual p. 1-18 to do a better way.%nnotes(nm1(1,:));%mypulsesalience(nm1(1,:));%interpulsesalience(nm1(1,:),nm1(1,:));%articulation(nm1(1,:));%majorkkcc(nm1(1,:));%minorkkcc(nm1(1,:));%stdp1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','pitch','std');%meanp1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','pitch','mean');%meanv1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','velocity','mean');%ton1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','maxkkcc');dens1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','nnotes')/wlen;%dur1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','duraccent','dur','mean');%ryt1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','mypulsesalience');     %%%% MYpulsesalience%ac1=ryt1(:,1);%tempo1=ryt1(:,2);%art1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','myarticulation');%%%t=tmin:wstep:tmax;%%%figure%%%plot(t,art1);%%%figure%%%plot(t,art1old);%dis1=dissonance3(nm1,1,wlen,wstep,tmin,tmax)';%maj1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','majorkkcc');%min1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','minorkkcc');if length(mc)>1    nm2=getmidich(nm,mc(2));	%stdp2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','pitch','std');	%meanp2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','pitch','mean');	%meanv2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','velocity','mean');	%ton2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','maxkkcc');	dens2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','nnotes')/wlen;	%dur2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','duraccent','dur','mean');	%ryt2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','mypulsesalience');     %%%% MYpulsesalience	%ac2=ryt2(:,1);    %tempo2=ryt2(:,2);    %art2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','myarticulation');    %%%art2old=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','articulation');    %%%figure    %%%plot(t,art2);    %%%figure    %%%plot(t,art2old);    %%%figure    %dis2=dissonance3(nm2,1,wlen,wstep,tmin,tmax)';    %maj2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','majorkkcc');    %min2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','minorkkcc');    %sil1=silence(nm1,nm2,5,2);    %sil2=silence(nm2,nm1,5,2);    syn=intermovewindow(nm1,nm2,wlen,wstep,tmin,tmax,'sec','interpulsesalience');    sync=syn(:,1);    %syntempo=syn(:,2);    %%%sync=filter((1:-.1:0)/sum(1:-.1:0),1,sync);    %rytspec1=mymovewindow(nm1,wlen,wstep,tmin,tmax,'sec','pulseac');    %for x=(1:size(rytspec1,1))    %    for y=(1:size(rytspec1,2))    %        if isnan(rytspec1(x,y))    %            rytspec1(x,y)=0;    %        end    %    end    %end    %%%imagesc(-rytspec1', [-.7 0])    %%%colormap(gray)    %rytspec2=mymovewindow(nm2,wlen,wstep,tmin,tmax,'sec','pulseac');    %for x=(1:size(rytspec2,1))    %    for y=(1:size(rytspec2,2))    %        if isnan(rytspec2(x,y))    %            rytspec2(x,y)=0;    %        end    %    end    %end    %%%figure    %%%imagesc(-rytspec2', [-.7 0])    %%%colormap(gray)    %%%figure    %%%rytspec=rytspec1.*rytspec2;    %%%imagesc(-rytspec', [-.2 0])    %%%colormap(gray)    %%%figure    %%%plot(ac1)    %%%axis tight    %%%figure    %%%plot(tempo1)    %%%axis tight    %%%figure     %%%plot(sync)    %%%axis tight    %%%figure    %%%plot(syntempo)    %%%axis tight    %%%figureelse    sil1=silence(nm1,nm1,5,2);    sync=0;endif col>-1t=tmin:wstep:tmax;clf; fsize=8;if length(mc)==1subplot('Position',[0.1 0.8 0.88 0.2]),pianoroll(nm1,'sec','hold');axis([tmin tmax get(gca,'YLim')]);  set(gca,'FontSize',fsize);else    subplot('Position',[0.1 0.9 0.88 0.095]),pianoroll(nm1,'sec','hold');axis([tmin tmax get(gca,'YLim')]);  set(gca,'FontSize',fsize);	subplot('Position',[0.1 0.8 0.88 0.095]),pianoroll(nm2,'sec','hold');axis([tmin tmax get(gca,'YLim')]); set(gca,'FontSize',fsize);endN=3; ypos=0.1+0.7*(1-(1:N)/N);n=0; dx=0.88; dy=0.7/N-0.005;if length(mc)>1 maxdens=max([dens1; dens2]); else maxdens=max(dens1);  endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,dens1,c1);if structstat    axis([tmin tmax 0 max(maxdens,stat.dens.mean+1*stat.dens.std,.1)])else    axis([tmin tmax 0 max(maxdens,.1)])endif length(mc)>1 hold on,plot(t,dens2,c2);hold off; endylabel('dens','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.dens.mean stat.dens.mean],'r--')plot([tmin tmax],[stat.dens.mean-1*stat.dens.std stat.dens.mean-1*stat.dens.std],'b:')plot([tmin tmax],[stat.dens.mean+1*stat.dens.std stat.dens.mean+1*stat.dens.std],'b:')endif 0if length(mc)>1 maxdur=max([dur1; dur2]); else maxdur=max(dur1); endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,dur1,c1);if structstat    axis([tmin tmax 0 max(maxdur,stat.dur.mean+1*stat.dur.std,.1)])else    axis([tmin tmax 0 max(maxdur,.1)])endif length(mc)>1 hold on, plot(t,dur2,c2);hold off; endylabel('dur','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.dur.mean stat.dur.mean],'r--')plot([tmin tmax],[stat.dur.mean-1*stat.dur.std stat.dur.mean-1*stat.dur.std],'b:')plot([tmin tmax],[stat.dur.mean+1*stat.dur.std stat.dur.mean+1*stat.dur.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,meanp1,c1); axis([tmin tmax 0 127])if length(mc)>1 hold on, plot(t,meanp2,c2);hold off; endylabel('meanp','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.meanp.mean stat.meanp.mean],'r--')plot([tmin tmax],[stat.meanp.mean-1*stat.meanp.std stat.meanp.mean-1*stat.meanp.std],'b:')plot([tmin tmax],[stat.meanp.mean+1*stat.meanp.std stat.meanp.mean+1*stat.meanp.std],'b:')endif length(mc)>1 pran=max([stdp1;stdp2]); else pran=max(stdp1); endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,stdp1,c1);if structstat    axis([tmin tmax 0 max(pran,stat.stdp.mean+1*stat.stdp.std,.1)])else    axis([tmin tmax 0 max(pran,.1)])endif length(mc)>1 hold on, plot(t,stdp2,c2); hold off; endylabel('stdp','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.stdp.mean stat.stdp.mean],'r--')plot([tmin tmax],[stat.stdp.mean-1*stat.stdp.std stat.stdp.mean-1*stat.stdp.std],'b:')plot([tmin tmax],[stat.stdp.mean+1*stat.stdp.std stat.stdp.mean+1*stat.stdp.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,meanv1,c1); axis([tmin tmax 0 127])if length(mc)>1 hold on, plot(t,meanv2,c2); hold off; endylabel('meanv','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.meanv.mean stat.meanv.mean],'r--')plot([tmin tmax],[stat.meanv.mean-1*stat.meanv.std stat.meanv.mean-1*stat.meanv.std],'b:')plot([tmin tmax],[stat.meanv.mean+1*stat.meanv.std stat.meanv.mean+1*stat.meanv.std],'b:')endif length(mc)>1 acran=max([ac1;ac2]); else acran=max(ac1); endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,ac1,c1);if structstat    axis([tmin tmax 0 max(acran,stat.ac.mean+1*stat.ac.std,.1)])else    axis([tmin tmax 0 max(acran,.1)])endif length(mc)>1 hold on, plot(t,ac2,c2); hold off; endylabel('ryth','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.ac.mean stat.ac.mean],'r--')plot([tmin tmax],[stat.ac.mean-1*stat.ac.std stat.ac.mean-1*stat.ac.std],'b:')plot([tmin tmax],[stat.ac.mean+1*stat.ac.std stat.ac.mean+1*stat.ac.std],'b:')endendif max(sync)n=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,sync,c1); axis([tmin tmax 0 max(sync)])ylabel('sync','FontSize',fsize); set(gca,'FontSize',fsize);if structstat    if (stat.players == 2)hold onplot([tmin tmax],[stat.sync.mean stat.sync.mean],'r--')plot([tmin tmax],[stat.sync.mean-1*stat.sync.std stat.sync.mean-1*stat.sync.std],'b:')plot([tmin tmax],[stat.sync.mean+1*stat.sync.std stat.sync.mean+1*stat.sync.std],'b:')    endendif 0if length(mc)>1 temporan=max([tempo1;tempo2]); else temporan=max(tempo1); endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,tempo1,c1);if structstat    axis([tmin tmax 0 max(temporan,stat.tempo.mean+1*stat.tempo.std,.1)])else    axis([tmin tmax 0 max(temporan,.1)])endif length(mc)>1 hold on, plot(t,tempo2,c2); hold off; endylabel('tempo','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.tempo.mean stat.tempo.mean],'r--')plot([tmin tmax],[stat.tempo.mean-1*stat.tempo.std stat.tempo.mean-1*stat.tempo.std],'b:')plot([tmin tmax],[stat.tempo.mean+1*stat.tempo.std stat.tempo.mean+1*stat.tempo.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,syntempo,c1); axis([tmin tmax 0 max(syntempo)])ylabel('syntempo','FontSize',fsize); set(gca,'FontSize',fsize);if structstat        if (stat.players == 2)hold onplot([tmin tmax],[stat.syntempo.mean stat.syntempo.mean],'r--')plot([tmin tmax],[stat.syntempo.mean-1*stat.syntempo.std stat.syntempo.mean-1*stat.syntempo.std],'b:')plot([tmin tmax],[stat.syntempo.mean+1*stat.syntempo.std stat.syntempo.mean+1*stat.syntempo.std],'b:')        endendendendif 0n=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,ton1,c1); axis([tmin tmax 0 1])if length(mc)>1 hold on, plot(t,ton2,c2);hold off; endylabel('ton','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.ton.mean stat.ton.mean],'r--')plot([tmin tmax],[stat.ton.mean-1*stat.ton.std stat.ton.mean-1*stat.ton.std],'b:')plot([tmin tmax],[stat.ton.mean+1*stat.ton.std stat.ton.mean+1*stat.ton.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,maj1,c1); axis([tmin tmax 0 1])if length(mc)>1 hold on, plot(t,maj2,c2);hold off; endylabel('maj','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.maj.mean stat.maj.mean],'r--')plot([tmin tmax],[stat.maj.mean-1*stat.maj.std stat.maj.mean-1*stat.maj.std],'b:')plot([tmin tmax],[stat.maj.mean+1*stat.maj.std stat.maj.mean+1*stat.maj.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,min1,c1); axis([tmin tmax 0 1])if length(mc)>1 hold on, plot(t,min2,c2);hold off; endylabel('min','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.min.mean stat.min.mean],'r--')plot([tmin tmax],[stat.min.mean-1*stat.min.std stat.min.mean-1*stat.min.std],'b:')plot([tmin tmax],[stat.min.mean+1*stat.min.std stat.min.mean+1*stat.min.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,art1,c1); axis([tmin tmax 0 1])if length(mc)>1 hold on, plot(t,art2,c2);hold off; endylabel('art','FontSize',fsize); set(gca,'FontSize',fsize);if structstathold onplot([tmin tmax],[stat.art.mean stat.art.mean],'r--')plot([tmin tmax],[stat.art.mean-1*stat.art.std stat.art.mean-1*stat.art.std],'b:')plot([tmin tmax],[stat.art.mean+1*stat.art.std stat.art.mean+1*stat.art.std],'b:')endn=n+1;subplot('Position',[0.1 ypos(n) dx dy]),plot(t,dis1,c1); axis([tmin tmax 0 1])if length(mc)>1 hold on, plot(t,dis2,c2);hold off; endylabel('dis','FontSize',fsize); set(gca,'FontSize',fsize);if length(mc)>1    xlabel(['wlen =' num2str(wlen) ', silence1 = ' num2str(sil1*100) '%, silence2 = ' num2str(sil2*100) '%.'], 'FontSize',10)else    xlabel(['wlen =' num2str(wlen) ', silence = ' num2str(sil1*100)], 'FontSize',10)endif structstathold onplot([tmin tmax],[stat.dis.mean stat.dis.mean],'r--')plot([tmin tmax],[stat.dis.mean-1*stat.dis.std stat.dis.mean-1*stat.dis.std],'b:')plot([tmin tmax],[stat.dis.mean+1*stat.dis.std stat.dis.mean+1*stat.dis.std],'b:')endendendxlabel(['duration =' num2str(totdur) ' seconds'], 'FontSize',10)dens1b = dens1(~isnan(dens1));%dur1b = dur1(~isnan(dur1));%meanp1b = meanp1(~isnan(meanp1));%stdp1b = stdp1(~isnan(stdp1));%meanv1b = meanv1(~isnan(meanv1));%ac1b = ac1(~isnan(ac1));%tempo1b = tempo1(~isnan(tempo1));%ton1b = ton1(~isnan(ton1));%art1b = art1(~isnan(art1));%dis1b = dis1(~isnan(dis1));%maj1b = maj1(~isnan(maj1));%min1b = min1(~isnan(min1));if length(mc)>1    %syntempob = syntempo(~isnan(syntempo));    syncb = sync(~isnan(sync));else    sync = NaN(size(dens1));    syncb = NaN;    %syntempo = NaN(size(dens1));    %syntempob = NaN;end%data.stat(:,:,1) = [[mean(dens1b), var(dens1b)]; ... [mean(dur1b), var(dur1b)]; [mean(meanp1b), var(meanp1b)]; [mean(stdp1b), var(stdp1b)]; [mean(meanv1b), var(meanv1b)];%    ...[mean(ac1b), var(ac1b)]; [mean(tempo1b), var(tempo1b)]; [mean(ton1b), var(ton1b)];%    ...[mean(art1b), var(art1b)];%    ...[mean(dis1b), var(dis1b)]; [mean(maj1b), var(maj1b)];%    ...[mean(min1b), var(min1b)];%    [var(syncb), var(syntempob)];... [sil1 wlen]%    ];%data.raw = [dens1, ...dur1, meanp1, stdp1, meanv1, ac1, tempo1, ton1, art1, dis1, maj1, min1, %    syntempo];    if length(mc)>1    dens2b = dens2(~isnan(dens2));    %dur2b = dur2(~isnan(dur2));    %meanp2b = meanp2(~isnan(meanp2));    %stdp2b = stdp2(~isnan(stdp2));    %meanv2b = meanv2(~isnan(meanv2));    %ac2b = ac2(~isnan(ac2));    %tempo2b = tempo2(~isnan(tempo2));    %ton2b = ton2(~isnan(ton2));    %art2b = art2(~isnan(art2));    %dis2b = dis2(~isnan(dis2));    %maj2b = maj2(~isnan(maj2));    %min2b = min2(~isnan(min2));    data = [mean(dens2b); var(dens2b); mean(syncb); var(syncb); totdur];else    data = [];end